// n8n forms only have a Required rule, so URL shape is checked here.
// The slug derived from the URL is what matches this submission to its
// ose_applications row — there is no token in the form link.
const input = $input.first().json;
const rawUrl = String(input["Your collective's Open Collective URL"] || '').trim();
const match = rawUrl.match(/^(?:https?:\/\/)?(?:www\.)?opencollective\.com\/([A-Za-z0-9][A-Za-z0-9-]*)(?:[\/?#].*)?$/);
return [{ json: {
  slug: match ? match[1].toLowerCase() : '',
  contact_email: String(input['Contact email'] || '').trim(),
  url_ok: !!match,
} }];

const TEMPLATE = `Subject: We've got your form for {{ collective_name }}

Hi,

Your application form for {{ collective_name }} has arrived. A human will now go through
it — that usually takes a few days.

No action needed from you for now. We'll email you as soon as there's a decision. If you
need to add or change anything in the meantime, reply to this email.

— {{ org_name }}`;
const ORG_NAMES = { OSE: 'Open Source Europe' };
const row = $json; // the updated row returned by Record submission
const recipient = row.contact_email;
if (!recipient) throw new Error(`form confirmation: no contact email for ${row.slug}`);
const vars = { collective_name: row.collective_name, org_name: ORG_NAMES[row.org] || row.org };
const render = (tpl) => tpl.replace(/\{\{\s*(\w+)\s*\}\}/g, (m, key) => {
  const value = vars[key];
  if (value === undefined || value === null || value === '') {
    throw new Error(`form confirmation: missing "${key}" for ${row.slug}`);
  }
  return String(value);
});
const cut = TEMPLATE.indexOf('\n');
let subject = render(TEMPLATE.slice('Subject: '.length, cut));
const body = render(TEMPLATE.slice(cut).trimStart());
// DRY_RUN fails safe: only the exact string `false` releases mail to the applicant. Unset,
// empty, `1`, `yes` or a trailing space all suppress, so a dropped or mistyped line in .env
// cannot quietly start mailing real people. Going live is the deliberate act of writing
// DRY_RUN=false.
const suppressed = String($env.DRY_RUN || '').trim().toLowerCase() !== 'false';
if (suppressed) subject = `[DRY_RUN → would have gone to ${recipient}] ${subject}`;
const to = suppressed ? ($env.DRY_RUN_RECIPIENT || '') : recipient;
if (!to) throw new Error('form confirmation: DRY_RUN is not "false", so the email is suppressed, but DRY_RUN_RECIPIENT is empty');
return { json: { slug: row.slug, to, subject, body, suppressed } };

// This node sits after the email send, so the row comes from Record submission by name
// rather than from the input. The form handles one application per execution.
//
// The answers go into the thread so a reviewer never opens n8n. The contact email is
// deliberately not among them: it is on the row for whoever needs it, and the channel is a
// wider audience than the table.
//
// The collective's name and URL, and every answer, are the applicant's own words, so they
// are data, not markup: an answer of <!channel>, or a masked link like
// <https://evil.example|opencollective.com/theirs> in "Anything else we should know?",
// would otherwise be honoured by Slack in the reviewers' channel. Escape the three
// characters Slack treats as control characters, & first so the other two are not escaped
// twice, and escape after trimming so a truncation never cuts an entity in half. Only the
// applicant's values go through escapeSlack: the fixed labels keep their *bold* and the
// header keeps its :clipboard:, and org resolves from our own host list.
const ORG_NAMES = { OSE: 'Open Source Europe' };

const escapeSlack = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

// Question labels a reviewer recognises, in the order the form asks them.
const LABELS = [
  ['applicant_type', 'Applying as'],
  ['repository_url', 'Repository'],
  ['project_website', 'Website'],
  ['licence', 'Licence'],
  ['open_development', 'Open development'],
  ['community_home', 'Community home'],
  ['community_open', 'How the community is run'],
  ['legal_entity', 'Already a legal entity'],
  ['legal_entity_detail', 'Entity details'],
  ['operating_duration', 'Running since'],
  ['fundraising_to_date', 'Raised so far'],
  ['fundraising_goal', 'Target'],
  ['funding_sources', 'Expected funders'],
  ['expected_expenses', 'Expected expenses'],
  ['payee_countries', 'Payee countries'],
  ['activities', 'What it does'],
  ['mission_fit', 'Open source in Europe'],
  ['notes', 'Anything else'],
];

const trim = (value) => {
  const text = String(value == null ? '' : value).replace(/\s+/g, ' ').trim();
  if (!text) return '';
  return text.length > 300 ? `${text.slice(0, 300)}…` : text;
};

return $('Record submission').all()
  .filter((item) => item.json.slack_thread_ts && item.json.slack_channel_id)
  .map((item) => {
    const row = item.json;
    const org = ORG_NAMES[row.org] || row.org;

    let responses = {};
    try {
      responses = (JSON.parse(row.answers || '{}').responses) || {};
    } catch (error) {
      // A row whose answers are not valid JSON still deserves a thread reply saying the
      // form arrived. Better a header with no detail than no message at all.
      responses = {};
    }

    const lines = LABELS
      .map(([key, label]) => [label, trim(responses[key])])
      .filter(([, value]) => value)
      .map(([label, value]) => `• *${label}:* ${escapeSlack(value)}`);

    const text = [
      `:clipboard: *${escapeSlack(row.collective_name)}* submitted the application form and is ready for evaluation.`,
      `${escapeSlack(row.collective_url)} — applied to ${org}.`,
      lines.length ? '' : 'The form recorded no answers, which is worth a look.',
      ...lines,
    ].filter((line) => line !== '').join('\n');

    return { json: {
      slug: row.slug,
      channel: row.slack_channel_id,
      thread_ts: row.slack_thread_ts,
      text,
    } };
  });
